import React, { useRef, useState, useEffect } from 'react';
import styles from './PhoneInput.module.css';

const PhoneInput = ({ label, value, onChange, error, ...props }) => {
    const inputRef = useRef(null);
    const [caretPosition, setCaretPosition] = useState(0);

    // Формат: +375 (XX) XXX-XX-XX
    const formatPhone = (input) => {
        const digits = input.replace(/\D/g, '');

        if (digits.length === 0) return '';

        let formatted = '+375';

        // Добавляем код оператора
        if (digits.length >= 4) {
            const code = digits.slice(3, 5);
            formatted += ` (${code}`;
        } else if (digits.length > 3) {
            formatted += ` (${digits.slice(3)}`;
        }

        // Закрываем скобку и добавляем первую группу
        if (digits.length >= 5) {
            const firstGroup = digits.slice(5, 8);
            formatted += `) ${firstGroup}`;
        } else if (digits.length > 3) {
            formatted += `) ${digits.slice(3)}`;
        }

        // Добавляем вторую группу
        if (digits.length >= 8) {
            const secondGroup = digits.slice(8, 10);
            formatted += `-${secondGroup}`;
        }

        // Добавляем третью группу
        if (digits.length >= 10) {
            const thirdGroup = digits.slice(10, 12);
            formatted += `-${thirdGroup}`;
        }

        return formatted;
    };

    // Получение позиции курсора после вставки отформатированного значения
    const getCaretPosition = (oldValue, newValue, oldCaretPos, action = 'insert') => {
        const oldDigits = oldValue.replace(/\D/g, '');
        const newDigits = newValue.replace(/\D/g, '');

        if (action === 'delete') {
            // При удалении позиция уменьшается
            return Math.max(0, oldCaretPos - 1);
        }

        // При вставке
        if (newDigits.length > oldDigits.length) {
            // Определяем, где были добавлены цифры
            for (let i = 0; i < newDigits.length; i++) {
                if (i >= oldDigits.length || newDigits[i] !== oldDigits[i]) {
                    // Находим позицию в отформатированной строке для этой цифры
                    let count = 0;
                    for (let j = 0; j < newValue.length; j++) {
                        if (/\d/.test(newValue[j])) {
                            if (count === i) {
                                return j + 1;
                            }
                            count++;
                        }
                    }
                    break;
                }
            }
        }

        return oldCaretPos;
    };

    const handleChange = (e) => {
        const rawValue = e.target.value;
        const oldValue = value || '';
        const oldCaretPos = inputRef.current?.selectionStart || 0;

        // Определяем действие (вставка или удаление)
        const isDelete = rawValue.length < oldValue.length;

        const formatted = formatPhone(rawValue);

        // Вычисляем новую позицию курсора
        const newCaretPos = getCaretPosition(oldValue, formatted, oldCaretPos, isDelete ? 'delete' : 'insert');

        // Обновляем значение
        onChange({ target: { value: formatted } });

        // Восстанавливаем позицию курсора в следующем тике
        setTimeout(() => {
            if (inputRef.current) {
                inputRef.current.setSelectionRange(newCaretPos, newCaretPos);
            }
        }, 0);
    };

    const handleKeyDown = (e) => {
        // Запоминаем позицию курсора перед изменением
        setCaretPosition(inputRef.current?.selectionStart || 0);

        // Блокируем ввод букв
        if (e.key.length === 1 && !/[0-9]/.test(e.key) && e.key !== 'Backspace' && e.key !== 'Delete' && e.key !== 'ArrowLeft' && e.key !== 'ArrowRight' && e.key !== 'Tab') {
            e.preventDefault();
        }
    };

    const handlePaste = (e) => {
        e.preventDefault();
        const pastedText = e.clipboardData.getData('text');
        const digits = pastedText.replace(/\D/g, '');
        if (digits) {
            const formatted = formatPhone(digits);
            onChange({ target: { value: formatted } });
        }
    };

    return (
        <div className={styles.phoneGroup}>
            {label && <label className={styles.label}>{label}</label>}
            <div className={styles.phoneWrapper}>
                <input
                    ref={inputRef}
                    type="tel"
                    className={`${styles.phoneInput} ${error ? styles.error : ''}`}
                    value={value || ''}
                    onChange={handleChange}
                    onKeyDown={handleKeyDown}
                    onPaste={handlePaste}
                    placeholder="+375 (XX) XXX-XX-XX"
                    {...props}
                />
            </div>
            {error && <span className={styles.errorMessage}>{error}</span>}
        </div>
    );
};

export default PhoneInput;
